"use client";

import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog"; 
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

const TEMPLATES = [
  { id: "review", name: "Sprint Review" },
  { id: "retrospective", name: "Sprint Retrospective" },
  { id: "release", name: "Release Planning" },
  { id: "sprintplan", name: "Sprint Planning" },
  { id: "daily", name: "Daily Scrum" },
];

export default function TaskFormModal({ open, setOpen, onCreateTask }: any) {
  const [titel, setTitel] = useState("");
  const [templateId, setTemplateId] = useState("review");
  const [sprint, setSprint] = useState(1);
  const [datum, setDatum] = useState(new Date().toISOString().split('T')[0]);

  function handleSubmit() {
    if (!titel) return alert("Voer een titel in!");

    onCreateTask({
      id: Date.now(),
      titel,
      documentType: templateId,
      sprint,
      datum,
      content1: "",
      content2: "",
      content3: "",
    });

    setTitel("");
    setOpen(false);
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle className="text-2xl font-bold text-teal-300 uppercase tracking-tighter">
            Nieuw Scrum Document
          </DialogTitle>
        </DialogHeader>
        
        <div className="flex flex-col gap-5 mt-4">
          <div>
            <label className="text-[10px] text-teal-500 font-bold uppercase tracking-widest block mb-2">Template</label>
            <Select value={templateId} onValueChange={setTemplateId}>
              <SelectTrigger className="w-full bg-[#0b1233] border-teal-400/30 text-teal-200">
                <SelectValue placeholder="Kies een template" />
              </SelectTrigger>
              <SelectContent className="bg-[#0E153A] border-teal-400/30 text-teal-100">
                {TEMPLATES.map(t => (
                  <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div>
            <label className="text-[10px] text-teal-500 font-bold uppercase tracking-widest block mb-1">Titel</label>
            <Input value={titel} onChange={(e) => setTitel(e.target.value)} className="bg-[#0b1233] border-teal-400/30 text-white" />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[10px] text-teal-500 font-bold uppercase tracking-widest block mb-1">Sprint</label>
              <Input type="number" value={sprint} onChange={(e) => setSprint(+e.target.value)} className="bg-[#0b1233] border-teal-400/30" />
            </div>
            <div>
              <label className="text-[10px] text-teal-500 font-bold uppercase tracking-widest block mb-1">Datum</label>
              <Input type="date" value={datum} onChange={(e) => setDatum(e.target.value)} className="bg-[#0b1233] border-teal-400/30" />
            </div>
          </div>

          <Button onClick={handleSubmit} className="bg-gradient-to-r from-teal-400 to-fuchsia-500 text-black font-bold uppercase mt-2">
            Aanmaken
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}