"use client";

import { useState, useEffect } from "react";
import { useSession } from "next-auth/react";
import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/button";
import TaskFormModal from "@/components/tasks/TaskFormModal";
import { Textarea } from "@/components/ui/textarea";

export default function TasksPage() {
  const { data: session } = useSession();
  const [open, setOpen] = useState(false);
  const [items, setItems] = useState<any[]>([]);
  const [geselecteerdItem, setGeselecteerdItem] = useState<any>(null);

  // Verileri çek
  useEffect(() => {
    const loadData = async () => {
      try {
        const res = await fetch("/api/scrum-docs");
        if (res.ok) {
          const data = await res.json();
          const formatted = data.map((d: any) => ({ ...d, ...d.content }));
          setItems(formatted);
        }
      } catch (err) { console.error("Yükleme hatası"); }
    };
    loadData();
  }, []);

  // Yeni Kayıt Oluştur
  const handleCreateTask = async (nieuwItem: any) => {
    if (!session?.user?.id) {
      alert("Lütfen önce giriş yapın!");
      return;
    }

    try {
      const res = await fetch("/api/scrum-docs", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...nieuwItem,
          userId: session.user.id,
        }),
      });

      const result = await res.json();

      if (res.ok) {
        const formatted = { ...result, ...result.content };
        setItems([formatted, ...items]);
        setGeselecteerdItem(formatted);
        setOpen(false);
      } else {
        alert("Sunucu Hatası: " + result.error);
      }
    } catch (err) {
      alert("Bağlantı kurulamadı.");
    }
  };

  const updateField = (key: string, val: string) => {
    if (!geselecteerdItem) return;
    const guncel = { ...geselecteerdItem, [key]: val };
    setItems(items.map(i => (i.id === geselecteerdItem.id ? guncel : i)));
    setGeselecteerdItem(guncel);
  };

  return (
    <div className="min-h-screen w-full bg-[#070B24] text-teal-100 py-10 px-8">
      <TaskFormModal open={open} setOpen={setOpen} onCreateTask={handleCreateTask} />
      
      <Card className="max-w-7xl mx-auto bg-[#0E153A]/80 border-teal-400/30 min-h-[800px] overflow-hidden">
        <div className="grid grid-cols-12 h-full min-h-[800px]">
          {/* Sidebar */}
          <div className="col-span-3 border-r border-teal-400/20 p-6 bg-[#0b1233]/50">
            <Button onClick={() => setOpen(true)} className="w-full bg-teal-400 text-slate-900 font-bold mb-6">
              + NIEUW DOCUMENT
            </Button>
            <div className="space-y-2">
              {items.map((item) => (
                <div 
                  key={item.id} 
                  onClick={() => setGeselecteerdItem(item)}
                  className={`p-3 rounded-lg cursor-pointer border ${geselecteerdItem?.id === item.id ? "border-teal-400 bg-teal-400/10" : "border-transparent hover:bg-white/5"}`}
                >
                  <div className="text-[10px] text-fuchsia-400 font-bold uppercase">{item.documentType}</div>
                  <div className="text-white text-sm font-medium truncate">{item.titel}</div>
                </div>
              ))}
            </div>
          </div>

          {/* Editor */}
          <div className="col-span-9 p-12 overflow-y-auto h-[800px]">
            {geselecteerdItem ? (
              <div className="max-w-2xl mx-auto space-y-8">
                <h1 className="text-4xl font-black text-white italic">{geselecteerdItem.titel}</h1>
                <div className="space-y-6">
                   {/* Buraya döküman tipine göre field'lar gelecek (Önceki kodlardaki Switch-Case yapısı) */}
                   <p className="text-teal-400/60 italic">Düzenlemek için alanları doldurun...</p>
                   <Field label="Ana İçerik" value={geselecteerdItem.s1 || geselecteerdItem.geleerd} onChange={(v:string) => updateField("s1", v)} />
                </div>
              </div>
            ) : (
              <div className="h-full flex items-center justify-center opacity-20 text-2xl font-black italic">WorkSpace Dashboard</div>
            )}
          </div>
        </div>
      </Card>
    </div>
  );
}

function Field({ label, value, onChange }: any) {
  return (
    <div className="space-y-2">
      <label className="text-xs font-bold text-teal-300 uppercase pl-1">{label}</label>
      <Textarea 
        value={value || ""} 
        onChange={(e) => onChange(e.target.value)}
        className="bg-[#0b1233] border-teal-500/30 text-white min-h-[200px]"
      />
    </div>
  );
}